static public File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("Target directory is null");
    if (name == null) throw new IllegalArgumentException("File name is null");
    // Remove query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Normalize name to prevent traversal: replace backslashes with forward slash, then remove any leading '/'.
    // Use Path normalization.
    java.nio.file.Path normalized = java.nio.file.Paths.get(name).normalize();
    // If normalized path is absolute or contains ".." after normalization, reject.
    if (normalized.isAbsolute() || normalized.toString().contains("..")) {
        throw new IllegalArgumentException("Invalid file name: path traversal detected");
    }
    // Use only the file name part (no directories)
    String safeName = normalized.getFileName().toString();

    File file = new File(dir, safeName);
    // Verify canonical path stays within dir
    try {
        String dirPath = dir.getCanonicalPath();
        String filePath = file.getCanonicalPath();
        if (!filePath.startsWith(dirPath + java.io.File.separator)) {
            throw new IllegalArgumentException("File path escapes target directory");
        }
    } catch (java.io.IOException e) {
        throw new IllegalArgumentException("Failed to resolve file path", e);
    }

    // Determine prefix/suffix from safeName
    int dot = safeName.lastIndexOf('.');
    String prefix = dot < 0 ? safeName : safeName.substring(0, dot);
    String suffix = dot < 0 ? "" : safeName.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        file = new File(dir, newName);
        try {
            String filePath = file.getCanonicalPath();
            if (!filePath.startsWith(dir.getCanonicalPath() + java.io.File.separator)) {
                throw new IllegalArgumentException("Generated file path escapes target directory");
            }
        } catch (java.io.IOException e) {
            throw new IllegalArgumentException("Failed to resolve generated file path", e);
        }
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}

