/**
 * Default implementation of {@link URLConstructor}.
 *
 * The original implementation returned {@code request.getPathInfo()} directly,
 * which allowed an attacker to supply arbitrary path information (e.g. "../conf/web.xml")
 * and cause a path‑traversal or unauthorized forward.  The patched version
 * validates and sanitises the supplied path before returning a forward page.
 */
public class DefaultURLConstructor implements URLConstructor {

    /** Allowed JSP page names – only alphanumeric characters, dash or underscore,
     *  ending with ".jsp".  Adjust the pattern or add a whitelist if you need
     *  a stricter set of pages. */
    private static final Pattern VALID_FORWARD_PAGE =
            Pattern.compile("^[A-Za-z0-9_-]+\\.jsp$");

    /**
     * Returns a safe forward page name based on the request's {@code pathInfo}.
     *
     * <p>The method performs the following hardening steps:
     * <ul>
     *   <li>Null‑check – if no path info is supplied a default page is returned.</li>
     *   <li>URL‑decoding – converts any %XX encoding to plain characters.</li>
     *   <li>Normalization – uses {@link java.nio.file.Paths#normalize()} to collapse
     *       sequences such as {@code ".."} or {@code "."}.</li>
     *   <li>Traversal protection – rejects any result that still contains
     *       {@code ".."}, forward or backward slashes after normalization.</li>
     *   <li>Pattern validation – ensures the final string matches the whitelist
     *       regular expression (only simple JSP names are allowed).</li>
     * </ul>
     *
     * If any of the checks fail, a safe fallback page (e.g. {@code "error.jsp"})
     * is returned, preventing uncontrolled forwarding.
     *
     * @param request the HTTP request that triggered the forward.
     * @return a validated JSP page name suitable for forwarding.
     */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        // 1. Guard against a missing pathInfo.
        String rawPath = request.getPathInfo();
        if (rawPath == null) {
            // No path supplied – forward to a sensible default.
            return "default.jsp";
        }

        // 2. Strip a leading '/' that is typical for pathInfo.
        if (rawPath.startsWith("/")) {
            rawPath = rawPath.substring(1);
        }

        // 3. Decode any URL‑encoded characters (e.g. %2e%2e/).
        try {
            rawPath = URLDecoder.decode(rawPath, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            // UTF‑8 is guaranteed to be present; this block will never be reached.
        }

        // 4. Normalise the path to collapse ".." and "." segments.
        String normalized = Paths.get(rawPath).normalize().toString();

        // 5. Reject any traversal attempts that survived normalisation.
        if (normalized.contains("..")
                || normalized.contains("/")
                || normalized.contains("\\")) {
            return "error.jsp";
        }

        // 6. Validate against the whitelist pattern.
        if (VALID_FORWARD_PAGE.matcher(normalized).matches()) {
            return normalized;               // safe forward page
        }

        // 7. Anything else is considered unsafe – forward to a generic error page.
        return "error.jsp";
    }

