        // Authentication failed - ensure context closed
        LdapUtils.closeContext(ctx);
        securityLog.warn(withRealm("LDAP authentication failed for user '%s' on server '%s': %s",
                principalStr, server(jndiFactory), ae.getMessage()));
        throw ae;
    } catch (IOException e) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                server(jndiFactory), e.getMessage()));
        throw new CommunicationException(e.getMessage(), e);
    } finally {
