     * Creates an {@link LdapContext} using STARTTLS and performs a proper bind
     * with the supplied {@code principal} and {@code credentials}. The method
     * ensures that authentication is performed over an encrypted channel and
     * that any failure results in the context being closed and the error being
     * logged without leaking sensitive information.
     *
     * @param ldapContextFactory the {@link LdapContextFactory} (must be a
     *                           {@link JndiLdapContextFactory})
     * @param principal          the LDAP bind DN or user name
     * @param credentials        the password for {@code principal}
     * @return an authenticated {@link LdapContext}
     * @throws NamingException if any LDAP operation fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {
        // --------------------------------------------------------------------
        // Validate inputs and factory type
        // --------------------------------------------------------------------
        if (!(ldapContextFactory instanceof JndiLdapContextFactory)) {
            throw new IllegalArgumentException("ldapContextFactory must be a JndiLdapContextFactory");
        }
        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("principal and credentials must not be null");
        }

        JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
        final String principalStr = principal.toString();
        final String credentialsStr = credentials.toString();

        // --------------------------------------------------------------------
        // Build the environment *before* creating the context so that the bind
        // information is available for the initial authentication step.
        // --------------------------------------------------------------------
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiFactory.getUrl());
        env.put(Context.SECURITY_AUTHENTICATION, jndiFactory.getAuthenticationMechanism());
        env.put(Context.SECURITY_PRINCIPAL, principalStr);
        env.put(Context.SECURITY_CREDENTIALS, credentialsStr);
        // Prevent automatic referral chasing which can be abused for injection
        env.put(Context.REFERRAL, "ignore");

        LdapContext ctx = null;
        StartTlsResponse tls = null;

        try {
            // ----------------------------------------------------------------
            // 1. Create the context (no TLS yet). The bind will be performed
            //    later after the channel is encrypted.
            // ----------------------------------------------------------------
            ctx = new InitialLdapContext(env, null);

            // ----------------------------------------------------------------
            // 2. Upgrade the connection to TLS using STARTTLS.
            // ----------------------------------------------------------------
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate(); // performs the TLS handshake

            // ----------------------------------------------------------------
            // 3. Re‑bind over the encrypted channel. The environment already
            //    contains the principal/credentials, so reconnect() will issue
            //    a proper LDAP bind using the secured socket.
            // ----------------------------------------------------------------
            ctx.reconnect(null);

            // ----------------------------------------------------------------
            // 4. Verify that the bind succeeded by performing a lightweight
            //    operation (reading the root DSE). If the bind failed an
            //    AuthenticationException will be thrown.
            // ----------------------------------------------------------------
            ctx.getAttributes("", null);

            return ctx; // authenticated and TLS‑protected context
        } catch (javax.naming.AuthenticationException authEx) {
            // Authentication failed – ensure resources are released and log
            // without exposing the password.
            LdapUtils.closeContext(ctx);
            securityLog.warn(withRealm("LDAP authentication failed for user '%s' on server '%s': %s",
                    principalStr, server(jndiFactory), authEx.getMessage()));
            throw authEx;
        } catch (IOException ioEx) {
            // TLS negotiation failed.
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                    server(jndiFactory), ioEx.getMessage()));
            throw new CommunicationException(ioEx.getMessage(), ioEx);
        } catch (Throwable t) {
            // Any other unexpected failure.
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Unexpected failure to negotiate TLS connection with '%s': %s",
                    server(jndiFactory), t.getMessage()));
            throw t;
        } finally {
            // ----------------------------------------------------------------
            // Clean up the STARTTLS response to free the underlying socket.
            // ----------------------------------------------------------------
            if (tls != null) {
                try {
                    tls.close();
                } catch (IOException ignored) {
                    // Ignored – nothing we can do at this point.
                }
            }
        }
    }
