import java.io.InputStream;
import java.io.IOException;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.XMLConstants;

/**
 * Secure XSLT renderer.
 *
 * The transformer is created with strict security settings:
 *  • FEATURE_SECURE_PROCESSING – enables the JAXP secure‑processing mode.
 *  • ACCESS_EXTERNAL_DTD – disables loading of external DTDs.
 *  • ACCESS_EXTERNAL_STYLESHEET – disables loading of external stylesheets.
 *
 * A fresh {@link TransformerFactory} instance is used for each call so that
 * the security configuration cannot be altered elsewhere in the application.
 */
public class XsltRenderer implements Renderer {

    // -----------------------------------------------------------------------
    //  Secure creation of a Transformer from an XSLT template stream
    // -----------------------------------------------------------------------
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("XSLT template stream must not be null");
        }

        // Use try‑with‑resources to guarantee the stream is closed even on failure
        try (InputStream is = templateStream) {
            // Create a *new* factory for each invocation – the static factory could be
            // re‑configured elsewhere, breaking the security guarantees.
            TransformerFactory factory = TransformerFactory.newInstance();

            // ---- Harden the factory -------------------------------------------------
            // Enable JAXP secure‑processing (limits resources, disables extensions)
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Disallow any external entity resolution (DTD, stylesheet, etc.)
            // Empty string means “no access”.
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");

            // -----------------------------------------------------------------------
            // Build the transformer from the (now safe) XSLT source
            // -----------------------------------------------------------------------
            return factory.newTransformer(new StreamSource(is));
        } catch (TransformerConfigurationException e) {
            // Wrap the checked exception in the application‑specific unchecked one
            throw new ProcessingFailedException("Failed to create XSLT transformer", e);
        } catch (Exception e) {
            // Any unexpected exception (e.g., IllegalArgumentException from setFeature)
            // is also wrapped to avoid leaking implementation details.
            throw new ProcessingFailedException("Unexpected error while creating XSLT transformer", e);
        }
    }

    // -----------------------------------------------------------------------
    //  other methods (unchanged)
    // -----------------------------------------------------------------------
}
