import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Secure expansion of archive entries.
 *
 * The implementation now:
 * <ul>
 *   <li>Normalises and resolves each entry against the real (canonical) target directory.</li>
 *   <li>Rejects absolute entry names.</li>
 *   <li>Ensures the resolved path is a descendant of the target directory, preventing
 *       path‑traversal attacks (e.g. “../” sequences, symbolic‑link tricks).</li>
 *   <li>Creates parent directories safely using {@link Files#createDirectories}.</li>
 *   <li>Writes entry data with explicit {@code CREATE} and {@code TRUNCATE_EXISTING}
 *       options to avoid accidental appends.</li>
 * </ul>
 */
public class Expander {

    // other methods ...

    /**
     * Expands the supplied archive entries into {@code targetDirectory} while protecting
     * against path‑traversal attacks.
     *
     * @param supplier        provides the next readable {@link ArchiveEntry}
     * @param writer          writes the entry data to an {@link OutputStream}
     * @param targetDirectory directory into which entries are extracted
     * @throws IOException if an I/O error occurs or a security check fails
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        final Path targetDir = targetDirectory.toPath()
                                              .toRealPath(LinkOption.NOFOLLOW_LINKS);

        ArchiveEntry nextEntry;
        while ((nextEntry = supplier.getNextReadableEntry()) != null) {

            String entryName = nextEntry.getName();
            if (entryName == null) {
                // Defensive: skip malformed entries.
                continue;
            }

            // Disallow absolute paths (e.g. "/etc/passwd" or "C:\temp").
            if (entryName.startsWith("/") || entryName.startsWith("\\")) {
                throw new IOException("Invalid entry name (absolute path not allowed): "
                                      + entryName);
            }

            // Normalise separators to '/' to make handling platform‑independent.
            entryName = entryName.replace('\\', '/');

            // Resolve the entry against the target directory and normalise the result.
            Path entryPath = targetDir.resolve(entryName).normalize();

            // Security check: the resolved path must stay within the target directory.
            if (!entryPath.startsWith(targetDir)) {
                throw new IOException("expanding " + nextEntry.getName()
                                      + " would create file outside of " + targetDirectory);
            }

            // At this point, entryPath is safe to use.
            if (nextEntry.isDirectory()) {
                // Ensure the directory exists.
                Files.createDirectories(entryPath);
            } else {
                // Ensure parent directory exists.
                Path parent = entryPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }

                // Write the entry data atomically.
                try (OutputStream out = Files.newOutputStream(entryPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }
        }
    }

    // other methods ...

}
