/**
 * Implementation of read for STORED entries.
 *
 * This method has been hardened against crafted ZIP streams that can
 * otherwise cause an infinite read loop.  The fixes are:
 *
 * <ul>
 *   <li>Validate the declared entry size – a negative size is treated as
 *       “unknown” and the method falls back to a plain stream‑read until EOF.</li>
 *   <li>Guard against {@link InputStream#read(byte[])} returning {@code 0}
 *       (or a negative value other than {@code -1}).  Such a result is
 *       interpreted as EOF to avoid a non‑progressing loop.</li>
 *   <li>Perform the EOF check only when the size is known.</li>
 *   <li>Limit the number of bytes returned to the caller to the remaining
 *       declared size when the size is known.</li>
 * </ul>
 *
 * These changes ensure that the method always terminates correctly,
 * even when presented with malformed or malicious ZIP data.
 */
private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Entries that use a data descriptor are handled elsewhere.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();               // cache the entry data
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    // The size may be unknown (e.g., -1) for malformed archives.
    final long declaredSize = current.entry.getSize();

    // If the size is known and we have already read it all, signal EOF.
    if (declaredSize >= 0 && current.bytesRead >= declaredSize) {
        return -1;
    }

    // Refill the internal buffer when it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        // Read directly into the backing array of the ByteBuffer.
        final int bytesRead = in.read(buf.array(), 0, buf.array().length);
        // Defensive check: treat 0 or negative (except -1) as EOF.
        if (bytesRead <= 0) {
            return -1;
        }
        buf.limit(bytesRead);
        count(bytesRead);
        current.bytesReadFromStream += bytesRead;
    }

    // Determine how many bytes we can safely return.
    int toRead = Math.min(buf.remaining(), length);
    if (declaredSize >= 0) {
        long remaining = declaredSize - current.bytesRead;
        if (remaining < toRead) {
            toRead = (int) remaining;
        }
    }

    // Transfer the bytes to the caller's buffer.
    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
