        // Defensive constants – they guarantee termination even if the
        // adjustment logic is somehow unable to make forward progress.
        // -----------------------------------------------------------------
        final int MAX_ITERATIONS = 10_000; // generous upper‑bound for realistic cron expressions
        int iterationCount = 0;

