        int toMinor = parseComponent(toArr, 1);
        int toPatch = parseComponent(toArr, 2);

        // Compare major, then minor, then patch – identical to the original logic.
        if (fromMajor != toMajor) {
            return fromMajor - toMajor;
        }
        if (fromMinor != toMinor) {
