 * </ul>
 * After the ownership check, the method continues to verify that no
 * immutable fields have been altered, using {@link Objects#equals}
 * to guard against {@code null} values.</p>
 *
 * <p>This approach eliminates the impersonation vulnerability while
 * preserving the original intent of allowing legitimate self‑updates.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming HTTP request is allowed to update the
     * user identified by the URL path variable.
     *
     * @param request the HTTP request containing the JSON payload
     * @return {@code true} if the update is authorised and immutable fields
     *         have not been tampered with; {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // -----------------------------------------------------------------
        // 1. Parse request payload
        // -----------------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            // Empty payload – nothing to validate, deny to be safe
            return false;
        }
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // -----------------------------------------------------------------
        // 2. Resolve target user ID from the request URL
        // -----------------------------------------------------------------
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );

        // -----------------------------------------------------------------
        // 3. Retrieve the persisted user record (or treat missing user as
        //    allowed – the caller will later receive a 404 from the
        //    provisioning layer)
        // -----------------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, the caller cannot be updating it.
            // Returning true lets the provisioning layer surface the proper
            // 404/404‑like response; the security check is irrelevant.
            return true;
        }

        // -----------------------------------------------------------------
        // 4. Authorisation check – ensure the caller is the owner or an admin
        // -----------------------------------------------------------------
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication == null || !authentication.isAuthenticated()) {
            return false; // unauthenticated request
        }

        // Determine the principal's identifier (could be a ScimUser, a
        // UserDetails implementation, or a plain String)
        String principalId = extractPrincipalId(authentication.getPrincipal());

        // Admins are allowed to modify any user
        boolean isAdmin = authentication.getAuthorities().stream()
                .map(GrantedAuthority::getAuthority)
                .anyMatch(auth -> auth.equalsIgnoreCase("uaa.admin") || auth.equalsIgnoreCase("ROLE_ADMIN"));

        if (!isAdmin && !Objects.equals(principalId, scimUserFromDb.getId())) {
            // The caller is neither admin nor the owner of the account
            return false;
        }

        // -----------------------------------------------------------------
        // 5. Immutable‑field validation – ensure the request does not try to
        //    change fields that are not allowed to be self‑updated.
        // -----------------------------------------------------------------
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed
        return true;
    }

    /**
     * Helper that extracts a stable identifier from the authentication principal.
     *
     * @param principal the principal object from {@link Authentication}
     * @return a string identifier (user ID) or {@code null} if it cannot be
     *         determined
     */
    private String extractPrincipalId(Object principal) {
        if (principal instanceof ScimUser) {
            return ((ScimUser) principal).getId();
        }
        if (principal instanceof UserDetails) {
            return ((UserDetails) principal).getUsername();
        }
        if (principal instanceof String) {
            return (String) principal;
        }
        // Unknown principal type – cannot safely determine identity
        return null;
    }

    // other methods (unchanged)
}
